'use strict';
let deckFavoritesBusy=false,deckFavoritesReady=false;
const deckFavoriteEl=id=>document.getElementById(id);
function deckFavoriteStatus(text){deckFavoriteEl('deck-favorites-status').textContent=text;}
function updateDeckFavoriteForm(){const slot=Number(deckFavoriteEl('deck-favorite-slot').value),existing=(gameState.deckFavorites||[]).find(v=>v.slot===slot),team=gameState.deck.map(id=>gameState.inventory.find(i=>i.instanceId===id)).filter(Boolean);deckFavoriteEl('deck-favorite-current').textContent='登録する編成：'+(team.length?team.map(i=>i.char).join('・'):'文字を3体編成してください');deckFavoriteEl('deck-favorite-target-note').textContent=existing?`お気に入り${slot+1}「${existing.name}」を、現在の編成で上書きします。別の編成を残す場合は未登録の保存先を選んでください。`:`お気に入り${slot+1}は未登録です。現在の編成を新しく保存します。`;deckFavoriteEl('btn-deck-favorite-save').textContent=existing?'現在の編成で上書き登録':'現在の編成をお気に入り登録';}
window.openDeckFavoriteRegistration=()=>{const panel=deckFavoriteEl('deck-favorites-panel');panel.open=true;updateDeckFavoriteForm();panel.scrollIntoView({block:'start',behavior:'smooth'});};
function renderDeckFavorites(){const box=deckFavoriteEl('deck-favorites-list');if(!box)return;box.replaceChildren();const list=gameState.deckFavorites||[];for(const v of list){const card=document.createElement('article'),name=document.createElement('strong'),info=document.createElement('p'),actions=document.createElement('div');name.textContent=`${v.slot+1}．${v.name}`;info.textContent=v.items.map(i=>`${i.char}（ルビ${i.equippedReadings.length}）`).join('・')+' ／ '+(v.formation?'保存した配置':'標準配置');for(const [label,fn]of [['呼び出す',()=>loadDeckFavorite(v.slot)],['更新する',()=>{deckFavoriteEl('deck-favorite-slot').value=v.slot;deckFavoriteEl('deck-favorite-name').value=v.name;updateDeckFavoriteForm();deckFavoriteStatus('保存先を選びました。内容を確認して「現在の編成で上書き登録」を押してください。');}],['削除',()=>removeDeckFavorite(v.slot)]]){const b=document.createElement('button');b.type='button';b.textContent=label;b.disabled=deckFavoritesBusy;b.onclick=fn;b.dataset.favoriteAction=label;b.dataset.favoriteSlot=v.slot;actions.append(b);}card.append(name,info,actions);box.append(card);}if(!list.length){const p=document.createElement('p');p.textContent='お気に入りはまだありません。';box.append(p);}deckFavoriteEl('btn-deck-favorite-save').disabled=deckFavoritesBusy;for(const option of deckFavoriteEl('deck-favorite-slot').children){const v=list.find(v=>v.slot===Number(option.value));option.textContent='お気に入り'+(Number(option.value)+1)+(v?'：'+v.name+'（登録済み）':'（未登録）');}updateDeckFavoriteForm();}
async function initializeDeckFavorites(){if(deckFavoritesBusy)return;deckFavoritesBusy=true;renderDeckFavorites();try{let r=await playerApi('/api/deck-favorites');if(gameState.deckFavoritesDeviceScopeVersion!==1){const previous=structuredClone(gameState.deckFavorites||[]);gameState.deckFavoritesSharedArchive=previous;for(const v of previous){if(r.favorites.some(f=>f.slot===v.slot)||!KanjiDeckFavorites.valid(v,c=>KANJI_DATABASE.some(i=>i.char===c))||!v.items.every(i=>gameState.inventory.some(owned=>owned.instanceId===i.instanceId&&owned.char===i.char)))continue;r=await playerApi('/api/deck-favorites/'+v.slot,'PUT',v);}gameState.deckFavoritesDeviceScopeVersion=1;}gameState.deckFavorites=r.favorites;deckFavoritesReady=true;if(!deckFavoriteEl('deck-favorite-name').value.trim()){const empty=Array.from({length:KanjiDeckFavorites.limit},(_,n)=>n).find(n=>!r.favorites.some(v=>v.slot===n));if(empty!==undefined)deckFavoriteEl('deck-favorite-slot').value=empty;}saveState();deckFavoriteStatus('最大10編成。文字の順番・装備ルビ・配置を端末（ブラウザ）ごとに保存します。');}catch(e){deckFavoriteStatus(e.status===401?'ゲストの接続を確認できません。記録画面で復元コードを確認してください。':'お気に入りを取得できません。「再取得」でお試しください。');}finally{deckFavoritesBusy=false;renderDeckFavorites();}}
window.saveDeckFavorite=async()=>{if(deckFavoritesBusy)return;const slot=Number(deckFavoriteEl('deck-favorite-slot').value),name=deckFavoriteEl('deck-favorite-name').value.trim(),items=gameState.deck.map(id=>gameState.inventory.find(i=>i.instanceId===id)).filter(Boolean).map(i=>({instanceId:i.instanceId,char:i.char,equippedReadings:getEquippedReadings(i).slice()})),formation=gameState.loadedDeckFormation||gameState.activeFormation!==null&&gameState.formationPresets[gameState.activeFormation]||null,value={name,items,formation:formation?KanjiFormation.copy(formation):null};if(!KanjiDeckFavorites.valid(value,c=>KANJI_DATABASE.some(i=>i.char===c))){deckFavoriteStatus('文字3体を編成し、20文字以内の編成名を入力してください。');return;}deckFavoritesBusy=true;renderDeckFavorites();try{const r=await playerApi('/api/deck-favorites/'+slot,'PUT',value);gameState.deckFavorites=r.favorites;deckFavoritesReady=true;saveState();deckFavoriteStatus(`「${name}」をお気に入り${slot+1}に登録しました。`);}catch(e){deckFavoriteStatus(e.status===401?'ゲストの接続を確認できません。記録画面で復元コードを確認してください。':`保存できませんでした。編成名は残っています。${e.message}`);}finally{deckFavoritesBusy=false;renderDeckFavorites();}};
window.loadDeckFavorite=slot=>{const v=gameState.deckFavorites?.find(v=>v.slot===slot);if(!v)return false;const r=KanjiDeckFavorites.resolve(v,gameState.inventory,getUnlockedReadings);if(r.missing.length){deckFavoriteStatus(`所持していない文字：${r.missing.join('・')}。編成は変更していません。`);return false;}stopDeckSwipe();r.items.forEach(({item,equippedReadings})=>{item.equippedReadings=equippedReadings;item.ruby=equippedReadings[0]||'';item.readingEquipped=!!equippedReadings.length;});gameState.deck=r.items.map(v=>v.item.instanceId);gameState.loadedDeckFormation=v.formation?KanjiFormation.fit(r.items.map(v=>v.item),v.formation).points:null;if(!v.formation)gameState.activeFormation=null;saveState();renderDeckSlots();renderCollection();updateBattleDeckSummary();deckFavoriteStatus(`「${v.name}」を呼び出しました。${r.rubies.length?'未解放のルビは外しました：'+r.rubies.join('・'):'レベルは現在の育成状況を使用します。'}`);return true;};
window.removeDeckFavorite=async slot=>{if(deckFavoritesBusy)return;const v=gameState.deckFavorites?.find(v=>v.slot===slot);if(!v||!confirm(`お気に入り「${v.name}」を削除しますか？`))return;deckFavoritesBusy=true;renderDeckFavorites();try{const r=await playerApi('/api/deck-favorites/'+slot+'/remove','POST',{});gameState.deckFavorites=r.favorites;saveState();deckFavoriteStatus(`「${v.name}」を削除しました。`);}catch(e){deckFavoriteStatus('削除できませんでした。'+e.message);}finally{deckFavoritesBusy=false;renderDeckFavorites();}};
window.addEventListener('load',()=>{const panel=document.createElement('details');panel.id='deck-favorites-panel';panel.className='deck-favorites-panel';panel.innerHTML='<summary>お気に入り編成（登録・呼び出し）</summary><ol class="favorite-steps"><li>上で文字3体・ルビ・配置を決める。</li><li>下で保存先を選び、編成名を入力する。</li><li>「現在の編成をお気に入り登録」を押す。</li></ol><p>文字の順番・装備ルビ・配置を保存します。呼び出すときは下の登録済み編成の「呼び出す」を押します。育成レベルは現在の状態を使用します。</p><p id="deck-favorite-current"></p><div class="deck-favorite-form"><label for="deck-favorite-slot">② 保存先<select id="deck-favorite-slot" onchange="updateDeckFavoriteForm()"></select></label><label for="deck-favorite-name">② 編成名<input id="deck-favorite-name" maxlength="20" placeholder="例：回転重視"></label></div><p id="deck-favorite-target-note" role="status" aria-live="polite"></p><button id="btn-deck-favorite-save" class="inventory-action" onclick="saveDeckFavorite()">現在の編成をお気に入り登録</button><p id="deck-favorites-status" role="status" aria-live="polite"></p><div id="deck-favorites-list"></div><button class="quiet-action" onclick="initializeDeckFavorites()">再取得</button>';const shortcut=document.createElement('button');shortcut.type='button';shortcut.id='btn-open-deck-favorite-registration';shortcut.className='inventory-action secondary';shortcut.textContent='現在の編成をお気に入り登録';shortcut.onclick=openDeckFavoriteRegistration;deckFavoriteEl('deck-order-status').after(shortcut,panel);for(let n=0;n<KanjiDeckFavorites.limit;n++){const o=document.createElement('option');o.value=n;o.textContent='お気に入り'+(n+1);deckFavoriteEl('deck-favorite-slot').append(o);}panel.addEventListener('toggle',()=>{if(panel.open){updateDeckFavoriteForm();if(!deckFavoritesReady)initializeDeckFavorites();}});renderDeckFavorites();});
